  right: 0px;
  float: right;
}

.accordion .accordion-tab label:where([dir="rtl"], [dir="rtl"] *)::before {
  left: 0px;
  float: left;
}

.accordion .accordion-tab label::before {
  top: 0;
  display: block;
  width: 1.5em;
  height: 1.5em;
  line-height: 1.5;
  font-size: 1.25rem;
  font-weight: bolder;
  text-align: center;
  transition: all .35s;
}

/* Tab content - open */

.accordion .accordion-tab input:checked ~ .tab-content {
  max-height: 3000vh;
}

/* Accordion icon formatting - closed */

.accordion .accordion-tab input[type=checkbox] + label:where([dir="ltr"], [dir="ltr"] *)::before {
  right: 5px;
}

.accordion .accordion-tab input[type=checkbox] + label:where([dir="rtl"], [dir="rtl"] *)::before {
  left: 5px;
}

.accordion .accordion-tab input[type=checkbox] + label::before {
  content: ">";
  transform: rotate(90deg);
}

/* Accordion icon formatting - open */

.accordion .accordion-tab input[type=checkbox]:checked + label::before {
  transform: rotate(270deg);
}

